import{_ as t,o as a,c as d,ai as o}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Modèles","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models.md","filePath":"fr/guide/models.md"}'),s={name:"fr/guide/models.md"};function n(r,e,i,l,c,m){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="modeles" tabindex="-1">Modèles <a class="header-anchor" href="#modeles" aria-label="Permalink to &quot;Modèles&quot;">​</a></h1><p>La page Modèles est un navigateur pour tous les modèles installés dans votre instance Ollama locale, avec des métadonnées détaillées et la détection des capacités.</p><p><strong>Élément de la barre latérale :</strong> Modèles <strong>Route :</strong> <code>/settings?tab=models</code></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page Modèles (accessible via l&#39;onglet Paramètres &gt; Modèles) affiche une carte ou une liste pour chaque modèle installé avec les informations essentielles en un coup d&#39;œil.</p><h2 id="details-des-modeles" tabindex="-1">Détails des modèles <a class="header-anchor" href="#details-des-modeles" aria-label="Permalink to &quot;Détails des modèles&quot;">​</a></h2><p>Chaque carte de modèle affiche :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Description</th></tr></thead><tbody><tr><td><strong>Nom</strong></td><td>Identifiant du modèle (par ex., <code>llama3.2:latest</code>)</td></tr><tr><td><strong>Nombre de paramètres</strong></td><td>Nombre de paramètres (par ex., 3B, 7B, 70B)</td></tr><tr><td><strong>Quantification</strong></td><td>Niveau de compression (par ex., Q4_0, Q8_0, F16)</td></tr><tr><td><strong>Famille</strong></td><td>Famille du modèle (par ex., llama, mistral, gemma)</td></tr><tr><td><strong>Format</strong></td><td>Format du modèle (par ex., gguf)</td></tr></tbody></table><h2 id="diagrammes-d-architecture" tabindex="-1">Diagrammes d&#39;architecture <a class="header-anchor" href="#diagrammes-d-architecture" aria-label="Permalink to &quot;Diagrammes d&#39;architecture&quot;">​</a></h2><p>Cliquez sur un modèle pour voir un diagramme d&#39;architecture montrant la structure interne du modèle -- nombre de couches, têtes d&#39;attention, dimensions d&#39;embedding, et plus encore. Ces informations sont extraites des métadonnées du modèle fournies par Ollama.</p><h2 id="detection-des-capacites" tabindex="-1">Détection des capacités <a class="header-anchor" href="#detection-des-capacites" aria-label="Permalink to &quot;Détection des capacités&quot;">​</a></h2><p>LLMxRay détecte automatiquement ce que chaque modèle peut faire. Les capacités sont lues <strong>en direct depuis Ollama</strong>, de sorte que les modèles récemment publiés fonctionnent sans aucune mise à jour côté LLMxRay. Lorsqu&#39;un modèle ne les signale pas lui-même, LLMxRay se rabat sur des patterns de nom.</p><p>Depuis <strong>Ollama 0.32</strong>, la liste des modèles (<code>/api/tags</code>) indique directement les capacités, la longueur de contexte et la largeur d&#39;embedding de chaque modèle. LLMxRay s&#39;appuie sur cette source en priorité : les icônes de capacité et le filtrage des modèles sont donc corrects dès le chargement de la liste, sans attendre un appel <code>/api/show</code> par modèle. <code>/api/show</code> continue de s&#39;exécuter en arrière-plan pour enrichir le cache (paramètres, template, métadonnées d&#39;architecture).</p><table tabindex="0"><thead><tr><th>Capacité</th><th>Comment elle est détectée</th><th>Effet sur l&#39;interface</th></tr></thead><tbody><tr><td><strong>Raisonnement</strong></td><td><code>capabilities</code> Ollama, sinon patterns de nom (<code>deepseek-r1</code>, <code>qwq</code>, <code>gpt-oss</code>, <code>magistral</code>, <code>nemotron</code>, <code>qwen3.x</code>, <code>muse-glimmer</code>, <code>glm-*</code>, <code>kimi-k*</code>, …)</td><td>Active l&#39;onglet raisonnement dans Diagnostics de Chat</td></tr><tr><td><strong>Vision</strong></td><td><code>capabilities</code> Ollama, sinon patterns de nom (<code>llava</code>, <code>*-vl</code>, <code>moondream</code>, <code>gemma3</code>, Llama-vision, …)</td><td>Active les pièces jointes images dans le chat</td></tr><tr><td><strong>Embedding</strong></td><td><code>capabilities</code> Ollama, sinon famille ou nom du modèle</td><td>Apparaît dans les sélecteurs de modèles des pages Plongements et Base de Connaissances</td></tr><tr><td><strong>Appel d&#39;outils</strong></td><td><code>capabilities</code> Ollama</td><td>Active l&#39;appel d&#39;outils dans le chat</td></tr></tbody></table><p>Comme les capacités proviennent directement d&#39;Ollama, LLMxRay suit automatiquement les nouvelles familles de modèles. Un ensemble de capacités signalé fait autorité : si le démon liste les capacités d&#39;un modèle <em>sans</em> y inclure <code>thinking</code>, LLMxRay le croit plutôt que de deviner d&#39;après le nom. Les patterns de nom ne s&#39;appliquent que lorsqu&#39;un modèle ne signale rien du tout.</p><p>Les modèles ne prenant en charge que les embeddings sont automatiquement filtrés des sélecteurs de modèles de chat.</p><h2 id="effort-de-raisonnement" tabindex="-1">Effort de raisonnement <a class="header-anchor" href="#effort-de-raisonnement" aria-label="Permalink to &quot;Effort de raisonnement&quot;">​</a></h2><p>Pour les modèles capables de raisonner, Diagnostics de Chat expose le paramètre <code>think</code> d&#39;Ollama :</p><table tabindex="0"><thead><tr><th>Réglage</th><th>Envoyé comme</th><th>Signification</th></tr></thead><tbody><tr><td><strong>Off</strong></td><td><em>(omis)</em></td><td>Aucun raisonnement interne</td></tr><tr><td><strong>On</strong></td><td><code>true</code></td><td>Raisonnement activé ; le modèle choisit lui-même son effort</td></tr><tr><td><strong>Faible / Moyen / Élevé</strong></td><td><code>&quot;low&quot;</code> / <code>&quot;medium&quot;</code> / <code>&quot;high&quot;</code></td><td>Budget de raisonnement explicite</td></tr><tr><td><strong>Max</strong></td><td><code>&quot;max&quot;</code></td><td>Budget de raisonnement maximal</td></tr></tbody></table><p>Les modèles qui n&#39;implémentent pas d&#39;effort gradué traitent simplement tout niveau comme « raisonnement activé ».</p><h2 id="dimensions-des-embeddings" tabindex="-1">Dimensions des embeddings <a class="header-anchor" href="#dimensions-des-embeddings" aria-label="Permalink to &quot;Dimensions des embeddings&quot;">​</a></h2><p>La page Plongements peut demander un vecteur de sortie plus étroit via le paramètre <code>dimensions</code> d&#39;Ollama (troncature Matryoshka). Laissez le champ vide pour la largeur native du modèle — affichée en placeholder, lue depuis la liste des modèles. Les modèles non entraînés pour la troncature Matryoshka renvoient leur largeur native quoi qu&#39;il arrive.</p><h2 id="catalogue-de-modeles" tabindex="-1">Catalogue de modèles <a class="header-anchor" href="#catalogue-de-modeles" aria-label="Permalink to &quot;Catalogue de modèles&quot;">​</a></h2><p>Le catalogue offre une vue organisée des modèles disponibles avec des tableaux comparatifs, vous aidant à choisir le modèle adapté à votre cas d&#39;utilisation.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Compromis de quantification</strong> -- Une quantification basse (Q4) utilise moins de RAM mais réduit légèrement la qualité. Q8 et F16 offrent une meilleure qualité mais nécessitent plus de mémoire.</li><li><strong>Télécharger d&#39;autres modèles</strong> depuis le terminal : <code>ollama pull &lt;nom-du-modele&gt;</code></li><li>La détection des capacités adapte l&#39;ensemble de l&#39;interface -- vous n&#39;avez rien à configurer manuellement.</li></ul>',26)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
